/*
 * A063872  Let m be the n-th positive integer such that phi(m) is divisible
 *          by m - phi(m). Then a(n) = phi(m)/(m - phi(m)).
 * https://oeis.org/A063872
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = A025473(n+1) - 1. Here a(n) is the (p-1) where p is the
 *            prime base of the n‑th prime power (>1) in increasing order. The
 *            sequence is generated by scanning integers, testing whether each
 *            integer is a prime power, and caching the results for arbitrary
 *            n
 * Range:     u8 n <= 70, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

/* ----------  Prime sieve  ---------------------------------------------- */
static uint32_t *prime_list = NULL;      /* array of primes */
static size_t    prime_cnt  = 0;          /* number of primes collected   */
static bool      primes_ready = false;   /* flag that primes are initialized */

static void init_primes(void)
{
    if (primes_ready) return;

    /* We generate a reasonably large list of primes (up to 1,000,000). */
    const idx_t sieve_limit = 1000000;
    bool *is_prime = (bool*)malloc((size_t)(sieve_limit + 1));
    if (!is_prime) return;                          /* out of memory */
    for (size_t i = 0; i <= sieve_limit; ++i) is_prime[i] = true;
    is_prime[0] = is_prime[1] = false;
    for (size_t i = 2; i * i <= (size_t)sieve_limit; ++i) {
        if (is_prime[i]) {
            for (size_t j = i * i; j <= (size_t)sieve_limit; j += i)
                is_prime[j] = false;
        }
    }

    /* count primes */
    for (size_t i = 2; i <= (size_t)sieve_limit; ++i)
        if (is_prime[i]) ++prime_cnt;

    /* allocate array and fill it */
    prime_list = (uint32_t*)malloc(prime_cnt * sizeof(uint32_t));
    size_t pos = 0;
    for (size_t i = 2; i <= (size_t)sieve_limit; ++i)
        if (is_prime[i]) prime_list[pos++] = (uint32_t)i;

    free(is_prime);
    primes_ready = true;
}

/* ----------  Cache of the sequence  ------------------------------------ */
static seq_t  *cache      = NULL;  /* cache of a(1), a(2), ... */
static size_t  cache_size = 0;     /* number of elements currently stored */
static size_t  cache_cap  = 0;     /* capacity of the cache array */
static idx_t   next_m     = 2;     /* next integer to test for prime power */

/* grow cache array when needed */
static void grow_cache(size_t min_cap)
{
    if (cache_cap >= min_cap) return;
    size_t cap = cache_cap? cache_cap*2 : 4;
    while (cap < min_cap) cap <<= 1;
    seq_t *tmp = (seq_t*)realloc(cache, cap * sizeof(seq_t));
    if (!tmp) return; /* allocation failed, but will crash on use */
    cache = tmp;
    cache_cap = cap;
}

/* Ensure that cache contains at least the first n terms of the sequence. */
static void ensure_cache(idx_t n)
{
    if (!primes_ready) init_primes();
    if (!cache) { cache = NULL; cache_cap = 0; cache_size = 0; }

    while (cache_size < (size_t)n) {
        /* Test whether next_m is a prime power. */
        bool is_pp   = false;
        idx_t base   = 0;
        idx_t temp = next_m;

        /* trial division using precomputed primes */
        for (size_t i = 0; i < prime_cnt; ++i) {
            idx_t p = (idx_t)prime_list[i];
            if (p * p > temp) break;
            if (temp % p == 0) {
                while (temp % p == 0) temp /= p;
                if (temp == 1) { is_pp = true; base = p; }
                break;      /* divisor found; no need to test further */
            }
        }

        /* if no divisor found, the number is prime */
        if (!is_pp) {
            if (temp == next_m) {
                is_pp = true;
                base  = next_m;
            }
        }

        if (is_pp) {
            if (cache_size == cache_cap) grow_cache(cache_size + 1);
            cache[cache_size++] = (seq_t)(base - 1);   /* store p-1 */
        }

        ++next_m;   /* advance to the next integer to check */
    }
}

/* ----------  The required function  ------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* out of original offset, return 0 */
    ensure_cache(n);
    return cache[n - 1];
}
